parameters.jsCode:
const payload = $input.first().json.body || $input.first().json;
const author = payload.author || {};
const books = payload.books || [];
const logId = payload.notification_log_id || ('LOG_' + (author.author_id || 'AUTH') + '_' + Date.now());

let totalEarned = 0;
let totalPaid = 0;
let totalPending = 0;
let publishedList = [];
let productionList = [];

for (const b of books) {
  const earned = Number(b.total_royalty_earned) || 0;
  const paid = Number(b.royalty_paid) || 0;
  const pending = Number(b.royalty_pending) || 0;
  totalEarned += earned;
  totalPaid += paid;
  totalPending += pending;

  if (b.status === 'Published & Live') {
    publishedList.push(`- "${b.title}" (${b.genre}): ${b.total_copies_sold || 0} copies sold @ ₹${b.author_royalty_per_copy || 0}/copy. Total Earned: ₹${earned}, Paid: ₹${paid}, Pending: ₹${pending}. Last Payout: ${b.last_royalty_payout_date || 'None'}`);
  } else {
    productionList.push(`- "${b.title}" (Status: ${b.status})`);
  }
}

const meetsThreshold = totalPending >= 1000;
const isZero = totalPending === 0;

return {
  notification_log_id: logId,
  author_id: author.author_id || 'UNKNOWN',
  author_name: author.name || 'Author',
  author_email: author.email || '',
  city: author.city || '',
  total_earned: totalEarned,
  total_paid: totalPaid,
  total_pending: totalPending,
  meets_threshold: meetsThreshold,
  is_zero: isZero,
  published_summary: publishedList.length > 0 ? publishedList.join('\n') : 'No live publications',
  production_summary: productionList.length > 0 ? productionList.join('\n') : 'None'
};

