const prev = $('Deterministic Math & Formatting').first().json;
const aiRes = $input.first().json;
const emailContent = aiRes.choices?.[0]?.message?.content || '';

if (!emailContent || emailContent.length < 50) {
  throw new Error('AI email generation returned empty or invalid text');
}

return {
  log_id: prev.notification_log_id,
  author_name: prev.author_name,
  status: 'Success',
  summary_content: emailContent,
  completed_at: new Date().toISOString()
};
